package com.treasureverse.backend.sale;
import com.treasureverse.backend.common.entity.BaseTimeEntity; import com.treasureverse.backend.member.Member; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="sale_posts") public class SalePost extends BaseTimeEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="seller_id") private Member seller; @Column(nullable=false) private String title; @Column(nullable=false,columnDefinition="TEXT") private String content; @Column(nullable=false) private BigDecimal price; @Enumerated(EnumType.STRING) @Column(nullable=false) private SaleStatus status=SaleStatus.ON_SALE; protected SalePost(){} public SalePost(Member s,String t,String c,BigDecimal p){seller=s;title=t;content=c;price=p;} public Long getId(){return id;} public Long sellerId(){return seller.getId();} public String getTitle(){return title;} public BigDecimal getPrice(){return price;} public SaleStatus getStatus(){return status;} public void update(String t,String c,BigDecimal p,SaleStatus s){title=t;content=c;price=p;status=s;} }
